def opt(i, text, why): return {"id": i, "text": text, "rationale": why}
def Q(qid, nugget, typ, level, **kw):
    unit = nugget.split("-")[1]
    d = {"id": qid, "type": typ, "domain": "D2", "module": "M3", "unit": unit, "nugget": nugget, "level": level}
    d.update(kw)
    return d

